<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$matters=$pdo->query('SELECT m.id,m.matter_reference,m.subject,c.name FROM matters m JOIN clients c ON c.id=m.client_id WHERE m.status!="closed" ORDER BY m.updated_at DESC')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$title=aep_post_string('title',300);$matterId=(int)($_POST['matter_id']??0);if($title===''){$error='Task title is required.';}else{$due=aep_post_string('due_date',10);if($due!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)){$error='Enter a valid due date.';}else{$pdo->prepare('INSERT INTO tasks(matter_id,title,description,status,due_date) VALUES(?,?,?,?,?)')->execute([$matterId?:null,$title,aep_post_string('description',4000),aep_valid_status(aep_post_string('status',20),['open','in_progress','completed'],'open'),$due?:null]);aep_log_activity($pdo,'Tasks','Created '.$title);header('Location:task_view.php?id='.(int)$pdo->lastInsertId());exit;}}}
$pageTitle='Create Task | AEP';$activeNav='tasks';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:820px;margin:auto"><h1>Create Task</h1><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form method="post" class="grid grid-2" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Task title *</label><input required name="title"></div><div><label>Matter</label><select name="matter_id"><option value="">Unlinked task</option><?php foreach($matters as $matter):?><option value="<?php echo $matter['id'];?>" <?php echo (int)($_GET['matter_id']??0)===(int)$matter['id']?'selected':'';?>><?php echo aep_h($matter['matter_reference'].' — '.$matter['subject']);?></option><?php endforeach;?></select></div><div><label>Due date</label><input type="date" name="due_date"></div><div><label>Status</label><select name="status"><option value="open">Open</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select></div><div style="grid-column:1/-1"><label>Description</label><textarea name="description"></textarea></div><div class="actions"><button class="btn">Create task</button><a class="btn secondary" href="task_list.php">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
